/* Interleaved (re, im) pair
 * In C++ we use a plain struct so no C99 _Complex dependency is needed. */
#ifdef __cplusplus
    typedef struct { notorious_fft_real re, im; } notorious_fft_cmpl;
#else
    typedef notorious_fft_real notorious_fft_cmpl[2];
#endif

